DROP TABLE IF EXISTS ld_scoperhigher_resetdata;
CREATE TABLE ld_scoperhigher_resetdata LIKE ld_scoperhigher;
INSERT INTO ld_scoperhigher_resetdata(userid,viewid,scopeauthority,modulename)
SELECT userid,viewid,scopeauthority,modulename FROM ld_scoperhigher 
GROUP BY userid,viewid,scopeauthority,modulename;

TRUNCATE TABLE ld_scoperhigher;
INSERT INTO ld_scoperhigher(userid,viewid,scopeauthority,modulename)
SELECT userid,viewid,scopeauthority,modulename FROM ld_scoperhigher_resetdata;

DROP TABLE IF EXISTS ld_scoperhigher_resetdata;
