INSERT INTO ld_systems_deploy(deploy_value,deploy_type,description,sequence,presence)
SELECT '0','328','钉钉是否保存钉盘后预览(直接预览附件)','1','1' from dual
WHERE NOT EXISTS(SELECT 1 FROM ld_systems_deploy WHERE deploy_type='328');
delimiter;

CALL AddColumn('ld_groups','groupseq','int',11,0);
CALL DelColumn('ld_groups','sequence');
delimiter;

UPDATE ld_groups SET groupseq=0;
DELETE FROM ld_groups WHERE parentid IS NULL;
delimiter;

DROP PROCEDURE IF EXISTS `ldcrm_reset_groupseq`;
delimiter ||
CREATE PROCEDURE `ldcrm_reset_groupseq`(
)
BEGIN

	DECLARE tmp_id INT(19) DEFAULT 0;
	
	DECLARE MYCUSOR CURSOR FOR SELECT parentid FROM ld_groups GROUP BY parentid ORDER BY parentid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_id = NULL;

	OPEN MYCUSOR; 
	FETCH MYCUSOR INTO tmp_id;
	WHILE(tmp_id IS NOT NULL) DO
		SET @i=0;
		UPDATE ld_groups SET groupseq=(@i:=@i+1) WHERE parentid=tmp_id ORDER BY groupseq,groupid;
		FETCH MYCUSOR INTO tmp_id;
	END WHILE;
	CLOSE MYCUSOR;

END ||
delimiter;

CALL ldcrm_reset_groupseq();
DROP PROCEDURE IF EXISTS `ldcrm_reset_groupseq`;
-- 2021-07-28

INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
SELECT 'zh','loginfromadifferentlocation','您的账号在其他电脑上登录，您已被迫退出！','jspop' FROM DUAL 
WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'zh' AND labelbol='loginfromadifferentlocation' and Labeltype='jspop');
INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,labeltype)
SELECT 'en','loginfromadifferentlocation','Your account is logged in on other computers, you have been forced to quit! ','jspop' FROM DUAL 
WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE languagetype = 'en' AND labelbol='loginfromadifferentlocation' and Labeltype='jspop');
delimiter;

call AddColumn('ld_loginhistory','login_check','varchar',30,NULL);
delimiter;

SET @disable_triggers='lingdang';
UPDATE ld_account SET advance_stage=rating WHERE EXISTS (SELECT module_field FROM ld_settings_advance WHERE module='Accounts' AND module_field='rating');
SET @disable_triggers=NULL;
delimiter;
-- 2021-07-30

CALL addColumn('ld_customreport_total_column','column_module','varchar','100','');
delimiter;

SET @disable_triggers=NULL;
UPDATE ld_field_seq SET id=(SELECT MAX(fieldid) FROM ld_field);
UPDATE ld_blocks_seq SET id=(SELECT MAX(blockid) FROM ld_blocks);
UPDATE ld_relatedlists_seq SET id=(SELECT MAX(relation_id) FROM ld_relatedlists);
UPDATE ld_customview_seq SET id = (SELECT MAX(cvid) FROM ld_customview);
UPDATE ld_links_seq SET id=(SELECT MAX(linkid) FROM ld_links);
UPDATE ld_picklist_dependency_seq SET id=(SELECT MAX(id) FROM ld_picklist_dependency);
UPDATE ld_crmentity_seq SET id=(SELECT MAX(crmid) FROM ld_crmentity);
UPDATE ld_approve_seq SET id=(SELECT MAX(id) FROM ld_approve);
UPDATE ld_approvestep_seq SET id=(SELECT MAX(id) FROM ld_approvestep);
UPDATE ld_autotask_seq SET id = (SELECT MAX(autotaskid) FROM ld_autotask);
UPDATE ld_currency_info_seq SET id=(SELECT MAX(id) FROM ld_currency_info);
UPDATE ld_users_seq SET id=(SELECT MAX(id) FROM ld_users);
UPDATE ld_tabdetailfield_seq SET id=(SELECT MAX(tabdetailfieldid) FROM ld_tabdetailfield);
UPDATE ld_customreport_info_seq SET id=(SELECT MAX(report_id) FROM ld_customreport_info);
UPDATE ld_producttoolfield_seq SET id=(SELECT MAX(producttoolfieldid) FROM ld_producttoolfield);
UPDATE ld_settings_field_seq SET id=(SELECT MAX(fieldid) FROM ld_settings_field);
UPDATE ld_workreport_field_seq SET id=(SELECT MAX(id) FROM ld_workreport_field);
delimiter;

